<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>Global Economic Prospects Poster</title>
<style>
  :root{
    --navy:#0b2f4a;
    --blue:#145d82;
    --blue2:#1b77a5;
    --teal:#0f8f8c;
    --teal-dark:#0a6e72;
    --amber:#d99a22;
    --amber-light:#f4c86a;
    --ink:#1a2b36;
    --muted:#5c6f7b;
    --line:#d7e4ea;
    --panel:#f7fbfc;
    --panel2:#eef7f8;
    --white:#ffffff;
  }
  *{box-sizing:border-box}
  html,body{margin:0;background:#dfe8ec;font-family:"Liberation Sans","Arial",sans-serif;color:var(--ink)}
  .poster{
    width:2480px;height:3508px;background:#fbfdfd;position:relative;overflow:hidden;
    padding:132px 142px 108px 142px;
  }
  .poster:before{content:"";position:absolute;inset:0;background:
    radial-gradient(circle at 88% 5%, rgba(15,143,140,.13), transparent 520px),
    radial-gradient(circle at 8% 22%, rgba(217,154,34,.08), transparent 420px),
    linear-gradient(90deg, rgba(11,47,74,.035) 1px, transparent 1px),
    linear-gradient(0deg, rgba(11,47,74,.025) 1px, transparent 1px);
    background-size:auto,auto,92px 92px,92px 92px; pointer-events:none}
  .top-rule{position:absolute;left:0;right:0;top:0;height:28px;background:linear-gradient(90deg,var(--navy),var(--teal),var(--amber));}
  header{position:relative;display:grid;grid-template-columns:1.17fr .83fr;gap:78px;align-items:end;margin-bottom:70px}
  .eyebrow{font-size:32px;letter-spacing:5.5px;text-transform:uppercase;color:var(--teal-dark);font-weight:700;margin-bottom:28px}
  h1{font-size:112px;line-height:.98;margin:0;color:var(--navy);letter-spacing:-3.8px;font-weight:800}
  .subtitle{font-size:39px;line-height:1.32;color:#385261;margin-top:34px;max-width:1340px;font-weight:400}
  .header-card{background:var(--navy);border-radius:28px;padding:46px 48px;color:white;box-shadow:0 22px 48px rgba(11,47,74,.13);position:relative;overflow:hidden}
  .header-card:after{content:"";position:absolute;right:-150px;top:-130px;width:360px;height:360px;border-radius:50%;border:38px solid rgba(244,200,106,.22)}
  .kicker{font-size:27px;text-transform:uppercase;letter-spacing:3px;color:#a7d7dc;font-weight:700;margin-bottom:12px}
  .hero-num{font-size:93px;line-height:1;color:var(--amber-light);font-weight:800;letter-spacing:-2px;margin:0 0 12px}
  .hero-label{font-size:34px;line-height:1.22;color:#eaf6f7;margin:0;max-width:650px}
  .narrative{position:relative;display:grid;grid-template-columns:repeat(4,1fr);gap:22px;margin-bottom:48px}
  .arc-line{position:absolute;left:9%;right:9%;top:43px;height:5px;background:linear-gradient(90deg,var(--teal),var(--blue),var(--amber));opacity:.35}
  .arc-step{position:relative;background:white;border:1px solid var(--line);border-radius:22px;padding:76px 28px 28px;min-height:174px;box-shadow:0 8px 26px rgba(11,47,74,.045)}
  .arc-dot{position:absolute;top:24px;left:28px;width:44px;height:44px;border-radius:50%;background:var(--teal);border:8px solid #dff3f3;z-index:1}
  .arc-step:nth-child(3) .arc-dot{background:var(--blue)}
  .arc-step:nth-child(4) .arc-dot{background:var(--amber);border-color:#fff1cf}
  .arc-step:nth-child(5) .arc-dot{background:var(--navy);border-color:#dbe8ef}
  .arc-title{font-size:30px;font-weight:800;color:var(--navy);margin-bottom:8px}
  .arc-text{font-size:24px;line-height:1.25;color:var(--muted)}
  .metric-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:34px;margin-bottom:48px;position:relative}
  .recovery-card{background:linear-gradient(135deg,#0f556f,#0c8280);border-radius:30px;padding:48px;color:white;min-height:410px;display:grid;grid-template-columns:1fr .78fr;gap:34px;overflow:hidden;position:relative;box-shadow:0 18px 42px rgba(11,47,74,.12)}
  .recovery-card:after{content:"";position:absolute;right:-230px;bottom:-260px;width:650px;height:650px;border-radius:50%;background:rgba(255,255,255,.08)}
  .big-stat{font-size:118px;line-height:.96;font-weight:900;color:#fff;letter-spacing:-4px;margin-bottom:22px}
  .big-stat .accent{color:var(--amber-light)}
  .stat-label{font-size:37px;line-height:1.2;color:#e8fbfb;font-weight:700;max-width:760px}
  .recovery-note{font-size:27px;line-height:1.42;color:#def1f2;align-self:end;border-left:7px solid var(--amber-light);padding-left:24px;z-index:1}
  .divergence{background:white;border:1px solid rgba(215,228,234,.9);border-radius:28px;padding:42px;min-height:410px;box-shadow:0 10px 28px rgba(11,47,74,.055)}
  .mini-title{font-size:32px;line-height:1.1;text-transform:uppercase;letter-spacing:2px;color:var(--teal-dark);font-weight:800;margin-bottom:24px}
  .bar-row{margin:24px 0}
  .bar-label{font-size:27px;font-weight:700;color:var(--ink);display:flex;justify-content:space-between;margin-bottom:12px}
  .bar-track{height:32px;background:#e8f1f4;border-radius:999px;overflow:hidden}
  .bar-fill{height:100%;border-radius:999px;background:linear-gradient(90deg,var(--blue2),var(--teal))}
  .bar-fill.lag{width:55%;background:linear-gradient(90deg,#8fb2c1,#c5d6dd)}
  .bar-fill.adv{width:90%}
  .bar-fill.rob{width:78%}
  .caption{font-size:24px;line-height:1.38;color:var(--muted);margin-top:22px}
  .main{position:relative;display:grid;grid-template-columns:1.02fr .98fr;gap:42px;align-items:start}
  .section{background:white;border:1px solid var(--line);border-radius:30px;padding:40px 42px;box-shadow:0 12px 30px rgba(11,47,74,.048);margin-bottom:42px}
  .section.risk{border-top:14px solid var(--amber);padding-top:34px;background:linear-gradient(180deg,#fffaf0 0%,#ffffff 34%);box-shadow:0 18px 38px rgba(121,85,15,.10)}
  .section-title{display:flex;align-items:center;gap:18px;font-size:42px;line-height:1.08;color:var(--navy);font-weight:900;margin:0 0 26px;letter-spacing:-.7px}
  .title-mark{width:18px;height:54px;border-radius:999px;background:var(--teal)}
  .risk .title-mark{background:var(--amber)}
  .risk-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:22px;margin-top:12px}
  .risk-item{background:white;border:1px solid #eadbb7;border-radius:22px;padding:26px 28px;min-height:196px;position:relative;overflow:hidden}
  .risk-item.primary{grid-column:1 / -1;background:#fff4d9;border-color:#e4ba57;display:grid;grid-template-columns:auto 1fr;gap:25px;align-items:center;min-height:206px}
  .risk-icon{width:78px;height:78px;border-radius:19px;background:var(--amber);display:flex;align-items:center;justify-content:center;color:#fff;font-size:46px;font-weight:900;flex:0 0 auto}
  .risk-name{font-size:32px;font-weight:900;color:var(--navy);margin-bottom:9px}
  .risk-text{font-size:25px;line-height:1.32;color:#4d6270}
  .risk-item.primary .risk-name{font-size:38px}.risk-item.primary .risk-text{font-size:29px;color:#334b59}
  .policy-table{display:grid;grid-template-columns:175px 1fr 1fr;border:1px solid var(--line);border-radius:22px;overflow:hidden;margin-top:22px}
  .cell{padding:20px 21px;font-size:23px;line-height:1.28;border-bottom:1px solid var(--line);border-right:1px solid var(--line);background:#fff}
  .cell:nth-child(3n){border-right:0}.cell:nth-last-child(-n+3){border-bottom:0}
  .head{background:var(--navy);color:white;font-weight:800;font-size:24px;text-transform:uppercase;letter-spacing:1.2px}
  .area{font-weight:900;color:var(--blue);background:#f2f8fa}
  .targets{display:grid;grid-template-columns:repeat(2,1fr);gap:22px;margin-top:18px}
  .target-card{background:var(--panel);border:1px solid var(--line);border-radius:24px;padding:26px 24px;min-height:166px;position:relative}
  .target-card.wide{grid-column:1 / -1;display:grid;grid-template-columns:1fr 1fr;gap:22px;align-items:center;background:linear-gradient(90deg,#edf9f8,#fff7e7)}
  .target-value{font-size:48px;line-height:1;font-weight:900;color:var(--teal-dark);letter-spacing:-1.6px;margin-bottom:12px}
  .target-card:nth-child(2) .target-value,.target-card:nth-child(3) .target-value{color:var(--blue)}
  .target-card:nth-child(4) .target-value{color:#8a5d0d}
  .target-label{font-size:24px;line-height:1.24;font-weight:700;color:#425967}
  .youth-card{background:var(--navy);border-radius:28px;padding:34px 36px;color:white;margin-bottom:24px;display:grid;grid-template-columns:auto 1fr;gap:28px;align-items:center}
  .youth-num{font-size:82px;line-height:.92;color:var(--amber-light);font-weight:900;letter-spacing:-2.5px;white-space:nowrap}
  .youth-text{font-size:29px;line-height:1.25;color:#e8f6f8;font-weight:700}
  .theme-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px;margin-top:18px}
  .theme{border-left:7px solid var(--teal);background:#f7fbfc;border-radius:16px;padding:20px 22px;min-height:116px}
  .theme:nth-child(2),.theme:nth-child(5){border-left-color:var(--blue)}.theme:nth-child(3){border-left-color:var(--amber)}
  .theme-name{font-size:25px;font-weight:900;color:var(--navy);margin-bottom:7px}.theme-text{font-size:21px;line-height:1.28;color:var(--muted)}
  .callout-strip{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin:10px 0 42px}
  .callout{background:#ffffff;border:1px solid var(--line);border-radius:24px;padding:28px 30px;box-shadow:0 10px 26px rgba(11,47,74,.045)}
  .callout-num{font-size:56px;line-height:1;font-weight:900;color:var(--amber);letter-spacing:-1.5px;margin-bottom:10px}.callout-label{font-size:23px;line-height:1.2;color:#526b78;font-weight:700}
  footer{position:absolute;left:142px;right:142px;bottom:54px;display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--line);padding-top:24px;color:#667b86;font-size:22px}
  .source{max-width:1450px}.tag{font-weight:800;color:var(--navy);letter-spacing:2px;text-transform:uppercase}
</style>
</head>
<body>
  <div class="poster">
    <div class="top-rule"></div>
    <header>
      <div>
        <div class="eyebrow">World Bank • Global Economic Prospects</div>
        <h1>Resilience Amid Uncertainty</h1>
        <div class="subtitle">The global economy has recovered strongly from the 2020 recession, but vulnerable economies lag behind as trade tensions and policy uncertainty cloud the outlook.</div>
      </div>
      <div class="header-card">
        <div class="kicker">Recovery benchmark</div>
        <div class="hero-num">Strongest<br/>in 6 decades</div>
        <p class="hero-label">Last year's faster-than-expected growth capped a historically strong recovery — but the gains are uneven.</p>
      </div>
    </header>

    <div class="narrative">
      <div class="arc-line"></div>
      <div class="arc-step"><div class="arc-dot"></div><div class="arc-title">Strong recovery</div><div class="arc-text">Post-2020 rebound remains unmatched in six decades.</div></div>
      <div class="arc-step"><div class="arc-dot"></div><div class="arc-title">Emerging risks</div><div class="arc-text">Tariffs, uncertainty and market sentiment threaten momentum.</div></div>
      <div class="arc-step"><div class="arc-dot"></div><div class="arc-title">Policy action</div><div class="arc-text">Global coordination and domestic reforms can sustain growth.</div></div>
      <div class="arc-step"><div class="arc-dot"></div><div class="arc-title">Strategic priorities</div><div class="arc-text">2030 targets focus on jobs, services, infrastructure and inclusion.</div></div>
    </div>

    <div class="metric-grid">
      <div class="recovery-card">
        <div>
          <div class="mini-title" style="color:#bcebed">A Historic Recovery — But Uneven</div>
          <div class="big-stat"><span class="accent">6</span>-decade high</div>
          <div class="stat-label">Strongest recovery from a global recession since the 1960s.</div>
        </div>
        <div class="recovery-note">Headline resilience masks a widening gap: vulnerable emerging market and developing economies continue to lag advanced economies and stronger peers.</div>
      </div>
      <div class="divergence">
        <div class="mini-title">Divergence in resilience</div>
        <div class="bar-row"><div class="bar-label"><span>Advanced economies</span><span>higher resilience</span></div><div class="bar-track"><div class="bar-fill adv"></div></div></div>
        <div class="bar-row"><div class="bar-label"><span>Robust EMDE peers</span><span>moderate</span></div><div class="bar-track"><div class="bar-fill rob"></div></div></div>
        <div class="bar-row"><div class="bar-label"><span>Vulnerable EMDEs</span><span>falling behind</span></div><div class="bar-track"><div class="bar-fill lag"></div></div></div>
        <div class="caption">Conceptual index based on the report narrative: resilience is broad at the headline level, but uneven across economies.</div>
      </div>
    </div>

    <div class="main">
      <div class="left-col">
        <section class="section risk">
          <h2 class="section-title"><span class="title-mark"></span>Risks to the Outlook</h2>
          <div class="risk-grid">
            <div class="risk-item primary"><div class="risk-icon">!</div><div><div class="risk-name">Trade tensions & tariff effects</div><div class="risk-text">Escalating tariffs and retaliatory measures could disrupt supply chains, dampen investment and slow global demand.</div></div></div>
            <div class="risk-item"><div class="risk-name">Policy uncertainty</div><div class="risk-text">Unclear trade and macro policy paths can delay private investment and hiring.</div></div>
            <div class="risk-item"><div class="risk-name">Financial volatility</div><div class="risk-text">A sharp deterioration in sentiment could tighten financing conditions, especially for EMDEs.</div></div>
            <div class="risk-item"><div class="risk-name">Inventory correction</div><div class="risk-text">Firms that front-loaded purchases are drawing down stocks, reducing near-term demand.</div></div>
            <div class="risk-item"><div class="risk-name">Climate shocks</div><div class="risk-text">Extreme weather threatens agriculture, infrastructure and fiscal capacity in vulnerable regions.</div></div>
          </div>
        </section>

        <section class="section">
          <h2 class="section-title"><span class="title-mark"></span>Policy Actions for Sustained Growth</h2>
          <div class="policy-table">
            <div class="cell head">Area</div><div class="cell head">Global action</div><div class="cell head">Domestic action</div>
            <div class="cell area">Trade</div><div class="cell">Improve the multilateral trade environment</div><div class="cell">Diversify trade partners and products</div>
            <div class="cell area">Finance</div><div class="cell">Ease external financing constraints for EMDEs</div><div class="cell">Strengthen macroeconomic policy frameworks</div>
            <div class="cell area">Climate</div><div class="cell">Scale up mitigation and adaptation</div><div class="cell">Invest in resilient infrastructure</div>
            <div class="cell area">Investment</div><div class="cell">Catalyze private capital flows</div><div class="cell">Remove bottlenecks to business entry</div>
            <div class="cell area">Jobs</div><div class="cell">Support cross-border labor mobility</div><div class="cell">Enhance skills and labor flexibility</div>
          </div>
        </section>
      </div>

      <div class="right-col">
        <div class="callout-strip">
          <div class="callout"><div class="callout-num">1.2B</div><div class="callout-label">young people entering working age in the next decade</div></div>
          <div class="callout"><div class="callout-num">300M</div><div class="callout-label">people targeted for electricity access in Sub-Saharan Africa</div></div>
          <div class="callout"><div class="callout-num">1B+</div><div class="callout-label">people targeted for improved water security</div></div>
        </div>

        <section class="section">
          <h2 class="section-title"><span class="title-mark"></span>World Bank 2030 Strategic Priorities</h2>
          <div class="youth-card"><div class="youth-num">1.2 billion</div><div class="youth-text">youth entering working age makes inclusive job creation central to the World Bank Group mission.</div></div>
          <div class="targets">
            <div class="target-card"><div class="target-value">1.5B</div><div class="target-label">people reached with quality, affordable health services</div></div>
            <div class="target-card"><div class="target-value">300M</div><div class="target-label">people in Sub-Saharan Africa with electricity access through Mission 300</div></div>
            <div class="target-card"><div class="target-value">300M</div><div class="target-label">farmers helped to move up the agricultural value chain</div></div>
            <div class="target-card"><div class="target-value">80M</div><div class="target-label">women and women-led businesses with access to capital</div></div>
            <div class="target-card wide"><div><div class="target-value">1B+</div><div class="target-label">people with improved water security</div></div><div><div class="target-value">400M</div><div class="target-label">World Bank Group commitment under Water Forward</div></div></div>
          </div>
        </section>

        <section class="section">
          <h2 class="section-title"><span class="title-mark"></span>Key Research Themes in Recent Issues</h2>
          <div class="theme-grid">
            <div class="theme"><div class="theme-name">Fiscal policy</div><div class="theme-text">Fiscal rules, rebuilding fiscal space and small-state fiscal challenges.</div></div>
            <div class="theme"><div class="theme-name">Trade & supply chains</div><div class="theme-text">High trade costs, global value chains and pandemic-era disruptions.</div></div>
            <div class="theme"><div class="theme-name">Commodity markets</div><div class="theme-text">Commodity price cycles, energy shocks and policy responses.</div></div>
            <div class="theme"><div class="theme-name">Financial spillovers</div><div class="theme-text">Rising U.S. interest rates and rapid debt buildup dynamics.</div></div>
            <div class="theme"><div class="theme-name">Pandemic economics</div><div class="theme-text">COVID-19 effects on income inequality and regional macro outcomes.</div></div>
          </div>
        </section>
      </div>
    </div>

    <footer>
      <div class="source">Source: World Bank, <em>Global Economic Prospects</em> brief materials. Figures and targets reflect the supplied benchmark content.</div>
      <div class="tag">Data-forward policy poster • A1 portrait</div>
    </footer>
  </div>
</body>
</html>
